INSERT INTO users (id, email, name, img, pw_hash, pw_salt, pw_iter, verified, created, seen) VALUES ('stk-user8581', 'user8581@import.stkfupm.invalid', 'شدعوه', 'https://community.stkfupm.com/user_avatar/community.stkfupm.com/user8581/144/1829_2.png', '', '', 0, 0, 1794774613, 1794774613) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, img = EXCLUDED.img;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1474575-cie412', 'stk-user8581', 'CIE 412', 'info', '{"desc": "- ال Mechatronics يعتبر تخصص لحاله لكن في خطة التخصص هو عبارة عن كورس ( ليكشر + لاب )\nهذا الكورس موجود في قسم الميكانيكال لكن الماتيريال والكتاب اعتقد مختلفين ونفس الوقت مثل ماسمعت: إنهم متساهلين في جزئية ال control لأن الأغلب هذا اول كورس لهم في هذا المجال وممكن مايعرف بعض الأمور المتعلقة بالتحكم وبرمجة ال microcontrollers\n-\nطريقة تدريس الكورس تختلف على حسب الدكتور الي ماسك الكورس لكن غالبا ً يكون مراجعة تقريبا لهذي الكورسات\nee202 + ee203 +cise 302+ cise 313 +cise312 )\n\nطبعا المراجعة تكون سريعة و أغلب الكورس يكون مركز على اللاب والبروجكت مع شرح بسيط لبعض المواضيع مثلا : motors + robotics + matrices\n\nفلو كنت فاهم لهذي المواضيع , الكورس راح يكون سهل بالنسبة لك , اللهم تحتاج تدرب على بعض المسائل .\n\n- البروجكت : الخيار مفتوح لك لكن الأهم إن يكون له علاقة بالكورس يعني تدمج بين mechanical system و electrical system وهذا الشيئ بسيط لأن تقريبا أغلب المشاريع في تخصصنا فيها هذا الشيئ :\n\nمن المشاريع الي سوها الشباب هذا السمستر\nSmart Irrigation system + Solar Tracker system\nVending machine\nRobot arm\nquadcopter\n\nبإمكانك تطبق أفكار جديدة لكن خذ في بالك إن أغلب مشاريع Mechatronics تحتاج وقت ومعرفة ببعض الأشياء الي ممكن تكون جديدة عليك .\n\nاللاب بيكون على ال myrio و labview فحاول تتعلم عليهم لأن استخدامهم أسهل بكثير من ال arduino .\n\n- هذا السمستر الي درس الكورس كان maysorwala و أشغلنا الصراحة في البروجكت وشرحه أقل من العادي لكن لأن الكورس يعتبر مراجعة وتطبيق للي تعلمته في الكورسات الماضية تقدر تمشي حالك وتطلع بقريد لكن أهم شي ركز على البروجكت لأن عليه 40% - 35 % .\n\n- الكتاب ما استخدمناه ًإلا في شابتر , لكن إذا كان vaqar يدرس الكورس فالله يعينك , لازم تحل كل الأسئلة في الشابتر الي يشرحها لأنها راح تجي أسئلة مشابهة لها في الكويزات والميديترم ومافي سلوشن للكتاب فراح تتعب ومافي حل إلا إنكم توزعوا الأسئلة على بعض وكل واحد يحل سؤالين او ثلاثة و شاركوا الحلول بينكم .\n\nبشكل عام الكورس جميل خاصة لما تشتغل على البروجكت لكن الأهم هو الدكتور الي ماسك الكورس ممكن يخلي كورس ممتع وممكن يخليه غثيث\n\nرفعت ملفات للكورس على kfupm resources", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-412-mechatronics/120906/3", "user": "user8581", "ts": 1496686177000, "tid": 120906, "pn": 3}}', 1496686177000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
